using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Models;
namespace RaceDay.Api.Data;
public class RaceDayDbContext(DbContextOptions<RaceDayDbContext> options):DbContext(options) {
 public DbSet<UserRole> UserRoles=>Set<UserRole>(); public DbSet<Organizer> Organizers=>Set<Organizer>(); public DbSet<Participant> Participants=>Set<Participant>(); public DbSet<RaceEvent> Events=>Set<RaceEvent>(); public DbSet<EventCategory> EventCategories=>Set<EventCategory>(); public DbSet<Enrolment> Enrolments=>Set<Enrolment>(); public DbSet<RaceResult> Results=>Set<RaceResult>();
 protected override void OnModelCreating(ModelBuilder m) {
  m.Entity<UserRole>(e=>{e.ToTable("UserRole");e.HasKey(x=>x.RoleId);e.Property(x=>x.RoleName).HasMaxLength(30).IsRequired();e.HasIndex(x=>x.RoleName).IsUnique();e.HasData(new UserRole{RoleId=1,RoleName="Organiser"},new UserRole{RoleId=2,RoleName="Participant"});});
  m.Entity<Organizer>(e=>{e.ToTable("Organizers");e.HasKey(x=>x.OrganiserId);e.HasOne(x=>x.Role).WithMany().HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Restrict);e.Property(x=>x.FirstName).HasMaxLength(50).IsRequired();e.Property(x=>x.LastName).HasMaxLength(50).IsRequired();e.Property(x=>x.Email).HasMaxLength(100).IsRequired();e.HasIndex(x=>x.Email).IsUnique();e.Property(x=>x.PasswordHash).HasMaxLength(255).IsRequired();e.Property(x=>x.PhoneNumber).HasMaxLength(20);e.Property(x=>x.CreatedAt).HasDefaultValueSql("GETDATE()");});
  m.Entity<Participant>(e=>{e.ToTable("Participants");e.HasKey(x=>x.ParticipantId);e.HasOne(x=>x.Role).WithMany().HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Restrict);e.Property(x=>x.FirstName).HasMaxLength(50).IsRequired();e.Property(x=>x.LastName).HasMaxLength(50).IsRequired();e.Property(x=>x.Email).HasMaxLength(100).IsRequired();e.HasIndex(x=>x.Email).IsUnique();e.Property(x=>x.PasswordHash).HasMaxLength(255).IsRequired();e.Property(x=>x.PhoneNumber).HasMaxLength(20);e.Property(x=>x.DateOfBirth).HasColumnType("date");e.Property(x=>x.CreatedAt).HasDefaultValueSql("GETDATE()");});
  m.Entity<RaceEvent>(e=>{e.ToTable("Events");e.HasKey(x=>x.EventId);e.HasOne(x=>x.Organizer).WithMany(x=>x.Events).HasForeignKey(x=>x.OrganiserId).OnDelete(DeleteBehavior.Restrict);e.Property(x=>x.EventName).HasMaxLength(120).IsRequired();e.Property(x=>x.Description).HasMaxLength(500);e.Property(x=>x.EventType).HasMaxLength(30).IsRequired();e.Property(x=>x.Venue).HasMaxLength(150).IsRequired();e.Property(x=>x.City).HasMaxLength(80).IsRequired();e.Property(x=>x.Province).HasMaxLength(50).IsRequired();e.Property(x=>x.RouteInformation).HasMaxLength(500);e.Property(x=>x.CreatedAt).HasDefaultValueSql("GETDATE()");});
  m.Entity<EventCategory>(e=>{e.ToTable("EventCategories");e.HasKey(x=>x.CategoryId);e.HasOne(x=>x.Event).WithMany(x=>x.Categories).HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict);e.Property(x=>x.CategoryName).HasMaxLength(100).IsRequired();e.Property(x=>x.DistanceKm).HasPrecision(6,2);e.Property(x=>x.EntryFee).HasPrecision(10,2);e.Property(x=>x.CreatedAt).HasDefaultValueSql("GETDATE()");});
  m.Entity<Enrolment>(e=>{e.ToTable("Enrolments");e.HasKey(x=>x.EnrolmentId);e.HasOne(x=>x.Participant).WithMany(x=>x.Enrolments).HasForeignKey(x=>x.ParticipantId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.Category).WithMany(x=>x.Enrolments).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);e.HasIndex(x=>new{x.ParticipantId,x.CategoryId}).IsUnique();e.HasIndex(x=>x.RaceNumber).IsUnique().HasFilter("[RaceNumber] IS NOT NULL");e.Property(x=>x.Status).HasMaxLength(30).IsRequired();e.Property(x=>x.RaceNumber).HasMaxLength(30);e.Property(x=>x.EnrolmentDate).HasDefaultValueSql("GETDATE()");});
  m.Entity<RaceResult>(e=>{e.ToTable("Results");e.HasKey(x=>x.ResultId);e.HasOne(x=>x.Enrolment).WithOne(x=>x.Result).HasForeignKey<RaceResult>(x=>x.EnrolmentId).OnDelete(DeleteBehavior.Restrict);e.Property(x=>x.FinishTime).HasColumnType("time(0)");e.Property(x=>x.Status).HasMaxLength(30).IsRequired();e.Property(x=>x.RecordedAt).HasDefaultValueSql("GETDATE()");});
 }
}
